# -*- coding: utf-8 -*-
"""多穿库水位策略 —— policy(ctx) -> {sku_id: 水位箱数}

结构
----
两档水位 + 码板能力整形。

【主档】本窗(或当日更早窗)已揭示剩余需求的 SKU
  水位覆盖「还没走掉的整箱需求」:
      r = a_cur*rem_now + a_max*rem_今日滚动最大 - a_par*零包 - a_pp*已拣
  零包/拆零不按整箱备水位; 已进拣货流程的量已流出, 不重复占水位。
  再按「DS/FD 订单份额」与「STO 仓间调拨份额」加权 —— STO 当日兑现率低、系数更小,
  直接压浪费率; 之后叠加画像修正(优先级/库龄/件重/订单笔数)与决策窗系数,
  以及若干前瞻信号的线性修正(取本窗值与当日滚动最大值两路)。

【兜底档】当日尚无任何剩余需求信号的候选 SKU
  这批 SKU 仍然贡献可观的当日出货(实测部分工作日占全天出货件数 20%~32%),
  只靠主档无法把满足率拉过线。用现货/历史水位/投料前瞻/ESS 前瞻线性组合出一个
  保守水位, 并用「本 SKU 现货 + 立库折箱」封顶(备货不超过实际可动用量),
  再整体封顶, 低于阈值的丢掉。

【码板能力】某窗水位低于多穿库现货 => 差额码板退回立库, 码垛 1440 箱/h x 4h = 5760 箱/窗。
  超预算时按码板成本从大到小把该窗最贵的 SKU 摘出建议 —— 全天水位取六窗最大值,
  这些 SKU 在别的决策窗仍会给出水位, 相当于把码板作业错峰摊开, 不丢命中率。

参数由 repro/ 下的离线搜索(坐标下降 + CMA-ES, 目标=官方评估器 overall_score)标定。
"""

