def _cbk(x, cut):
    """连续量 -> 桶号 0..len(cut)。"""
    for _j, _c in enumerate(cut):
        if x < _c:
            return _j
    return len(cut)


# cut 递增时 _cbk(x,cut) == bisect_right(cut,x)(两者都是 min{j: x < cut[j]}, 否则 len)。
# 切点是被优化的自由参数、且同族 SPEC 量程互相重叠, 所以**不能假定**一定递增:
# 递增的用 C 实现的 _br, 不递增的退回 _cbk。逐位等价。
from bisect import bisect_right as _br

# v64 numpy 向量化: IX/IX3 内层改成整块 SKU 一起算。numpy 缺失时 _np=None,
# 两个块各自退回原来的逐 SKU 纯 Python 通路(两条路径逐位等价, 见 patch_v64_np.py)。
try:
    import numpy as _np
except Exception:                                    # pragma: no cover
    _np = None
_CUTA = {}


def _cutarr(cut):
    """切点列表 -> np 数组(按 id 记忆; 切点来自 P, 生命周期与模块同长)。"""
    a = _CUTA.get(id(cut))
    if a is None:
        a = _np.asarray(cut, dtype=_np.float64)
        _CUTA[id(cut)] = a
    return a


def _bkvec(BK, cv, n):
    """逐 (列,切点) 对给出整列桶号数组。递增切点用 searchsorted(= bisect_right),
    非递增退回 _cbk 的定义式(逆序折叠 np.where), 两者与标量版逐位相同。"""
    out = []
    for _ci, _cu, _s in BK:
        v = cv[_ci]
        if _s:
            out.append(_np.searchsorted(_cutarr(_cu), v, side='right'))
        else:
            r = _np.full(n, len(_cu), dtype=_np.intp)
            for _j in range(len(_cu) - 1, -1, -1):
                r = _np.where(v < _cu[_j], _j, r)
            out.append(r)
    return out


def _dense(tab, dims):
    """稀疏倍率表 -> 扁平 dense 数组(缺项 = 1.0)。缺项乘 1.0 逐位不改变乘积。"""
    n = 1
    for d in dims:
        n *= d
    a = _np.ones(n, dtype=_np.float64)
    for key, v in tab.items():
        f = 0
        for ax, d in zip(key, dims):
            f = f * d + ax
        a[f] = v
    return a


_IXD = None
_IX3D = None
if _np is not None:
    _IXD = [(_dense(_t[4], (len(_t[2]) + 1, len(_t[3]) + 1)), len(_t[3]) + 1)
            for _t in (P.get("ix") or ())]
    _IX3D = [(_dense(_t[6], (len(_t[3]) + 1, len(_t[4]) + 1, len(_t[5]) + 1)),
              len(_t[4]) + 1, len(_t[5]) + 1)
             for _t in (P.get("ix3") or ())]
# 小规模时 numpy 的固定开销盖过收益(实测 out 通常 ~200 个 SKU, 远在阈值之上)。
_NPMIN = 24


def _mkbk(pairs):
    """[(feat_or_None, cut)] -> (列表 cols, 桶化表 bks, 原位置->bks 下标 pos)。

    IX/IX3 内层原本逐表现算每个轴的桶号: 72 张三阶表 = 216 次 (dict.get + _cbk)。
    这里做**两级去重**:
      1. `cols` —— 不同的 (列, 切点) 对大量共用**同一列**(选表器 CUTMAP 给每列复用
         切点、错位表又只改切点), 所以稀疏字典的取值 `f.get(_k, 0.0)` 按列去重;
      2. `bks`  —— 桶号按 (列, 切点) 对去重。
    二阶实测 144 次轴查询 -> 22 列取值 + 92 次桶化; 三阶 216 -> 12 + 24。
    纯提公因式, 不改任何数值。"""
    cols, cpos, bks, bpos, out = [], {}, [], {}, []
    for f, cut in pairs:
        ck = id(f)
        if ck not in cpos:
            cpos[ck] = len(cols)
            cols.append(f)
        bk = (ck, tuple(cut))
        if bk not in bpos:
            bpos[bk] = len(bks)
            bks.append((cpos[ck], cut, list(cut) == sorted(cut)))
        out.append(bpos[bk])
    return cols, bks, out


def _pack(p):
    """板规 -> 件/箱。查 P["pkv"] 的逐板规估计表(单位 10 件);表缺省时退回
    原二值映射 84/104/105/125 -> 10、40/48/50/60 -> 20、缺失按 10。
    评分口径的 WASTE/FILL 分子分母都是**件数**, 所以件/箱估得准不准直接决定
    Dhat/rmain/Z 这些件数聚合量, 以及 trim / ε / rmx 三处排序谁先被摘。"""
    if not p:
        return 10.0
    try:
        pi = int(round(float(p)))
    except (TypeError, ValueError):
        return 10.0
    _t = P.get("pkv")
    if _t:
        v = _t.get(pi)
        if v is not None:
            return 10.0 * v
    return 20.0 if pi in _P20 else 10.0


def _pal_trim(out, sms, cap, tvw=None):
    """单窗码板量 sum(max(0, 现货-水位)) 超过码垛能力时, 摘掉码板成本最高的 SKU。

    摘掉一个 SKU 丢的是 min(水位, 实发) 件数(FILL 分子)加一个命中, 换回的是
    (现货-水位) 箱码板额度 —— 真正该先摘的是「码板成本 / 保留价值」最高的那批,
    而不是码板成本绝对值最大的那批。tvw(k, q) 返回该 SKU 的保留价值权重(中性 1.0);
    tvw=None 时退回纯码板成本序(与加这条通路之前逐位等价)。"""
    if cap <= 0 or not out:
        return
    pc = {k: (float(sms.get(k, 0) or 0) - q) for k, q in out.items()}
    tot = 0.0
    for v in pc.values():
        if v > 0:
            tot += v
    if tot <= cap:
        return
    if tvw is None:
        order = sorted(pc, key=lambda x: (-pc[x], x))
    else:
        pri = {}
        for k, c in pc.items():
            if c > 0:
                pri[k] = c / tvw(k, out[k])
        order = sorted(pri, key=lambda x: (-pri[x], x))
    for k in order:
        if tot <= cap:
            break
        c = pc[k]
        if c <= 0:
            break
        out.pop(k, None)
        tot -= c


# 当日滚动状态: 逐窗记住每个 SKU 各信号出现过的最大值(只用当前及更早决策窗的信息),
# 以及当日开工基线 shipped_today 与上一窗快照(用来造增量特征)。
_ST = {"pw": None, "mx": {}, "base": None, "psh": {}, "prem": {}, "fi": {}, "la": {}}

# 跨日状态: 逐日累计每个 SKU 的「昨日实发量」历史(只用已经过去的工作日, 严格因果)。
# 依据: shipped_today 在 w=0/1/2 三个窗上逐 SKU 完全相同、从 w=3 起才增长, 而当天开工
# 基线的值恰好等于**前一个工作日的日内增量**(逐 SKU 精确相等, 实测 64/64、90/90、104/104)。
# 也就是说每天开工时 ctx 免费送来一份「昨天到底发了哪些 SKU、各发多少」的已实现需求快照。
# 把它逐日累加成 EWMA / 出现频次 / 历史峰值, 就得到一组纯历史(因果)的 SKU 活跃度特征。
_H = {"days": 0, "ewm": {}, "cnt": {}, "mx": {}, "lag": {}, "sum": {}, "frq": {}, "avg": {},
      "pwd": {}, "rat": {}, "grat": 1.0, "seen": set(),
      # v45: 跨日历史的**分布形状**。nz[k] = 该 SKU 历史上非零实发量(升序), 配合 days
      # 就能把零日补齐, 算出任意分位。边际定价说最优水位 ≈ 当日需求分布的 ~9% 分位
      # (FILL 门下方约 40% 分位), 所以低分位才是理论上正确的下托量, 均值/EWMA 不是。
      "nz": {}, "p10": {}, "p25": {}, "p40": {}, "med": {}, "std": {}, "cmin": {}}
DELTA = ['rem', 'rem_bulk', 's_ms', 'ess', 'prod_ahead', 'water_hist', 'dps_today', 'rem_fd', 'asrs_box', 'air']
DELTA_SPEC = [('rem', 'rem_f', 'rem_up', 1.0), ('rem_bulk', 'bulk_f', 'bulk_up', 1.0), ('s_ms', 'sms_f', 'sms_dn', -1.0), ('ess', 'ess_f', 'ess_dn', -1.0), ('prod_ahead', 'pa_f', 'pa_dn', -1.0), ('water_hist', 'wh_f', 'wh_dn', -1.0), ('dps_today', 'dps_f', 'dps_up', 1.0), ('rem_fd', 'fd_f', 'fd_up', 1.0), ('asrs_box', 'as_f', 'as_dn', -1.0), ('air', 'air_f', 'air_up', 1.0)]
H_KEYS = ['h_lag', 'h_ewm', 'h_mx', 'h_frq', 'h_avg', 'h_p10', 'h_p25', 'h_p40', 'h_med', 'h_std', 'h_cmin']
LB_KEYS = ['rem_2nd', 'bulk_up', 'rem_up', 'fd_up', 'as_dn', 'air_up', 'ess_dn', 'pa_dn', 'sms_dn', 'sh_inc', 'rem_bulk', 'rem_fd', 'bulk_f', 'fd_f', 'rem_ds', 'rem', 'picked_prior', 'dps_up', 'wh_dn', 'rem_d', 'air_f', 'rem_drop', 'h_lag', 'h_ewm', 'h_mx', 'h_avg', 'dps_today', 'ess', 'prod_ahead', 'water_hist', 's_ms', 'asrs_box', 'shipped_today', 'sh_d', 'rem_f', 'sms_f', 'ess_f', 'pa_f', 'wh_f', 'n_orders', 'rem_parcel', 'as_f', 'h_p10', 'h_p25', 'h_p40', 'h_med', 'h_cmin']


def _hist_update(base):
    """用当天开工基线(=昨日实发量)推进跨日历史。周一基线全 0(周日不发货), 不计入。"""
    tot = 0.0
    for v in base.values():
        tot += v
    if tot <= 0:
        return
    lam = P["h_lam"]
    _H["days"] += 1
    _H["lag"] = dict(base)
    ewm = _H["ewm"]; cnt = _H["cnt"]; mx = _H["mx"]; sm = _H["sum"]
    for k in ewm:
        ewm[k] *= lam
    for k, v in base.items():
        if v <= 0:
            continue
        ewm[k] = ewm.get(k, 0.0) + (1.0 - lam) * v
        cnt[k] = cnt.get(k, 0) + 1
        sm[k] = sm.get(k, 0.0) + v
        if v > mx.get(k, 0.0):
            mx[k] = v
    dd = float(_H["days"])
    _H["frq"] = dict((k, v / dd) for k, v in cnt.items())
    _H["avg"] = dict((k, v / dd) for k, v in sm.items())
    _hist_dist(base)
    _cal_update(base)


def _hist_dist(base):
    """把每天的实发量攒成逐 SKU 的经验分布, 算出低分位 / 中位 / 离散度 / 条件最小值。

    零日不显式存储: nz[k] 只留非零值(升序), 已过天数 days 减去 len(nz) 就是零日数,
    分位查询时用零补齐。这样内存与排序成本都只跟"真发过货的次数"成正比。
    """
    nz = _H["nz"]
    for k, v in base.items():
        if v > 0:
            lst = nz.get(k)
            if lst is None:
                nz[k] = [v]
            else:
                lst.append(v)
    n = _H["days"]
    if n <= 0:
        return
    p10 = {}; p25 = {}; p40 = {}; med = {}; sd = {}; cmn = {}
    for k, lst in nz.items():
        lst.sort()
        z = n - len(lst)
        if z < 0:
            z = 0
        for q, tgt in ((0.10, p10), (0.25, p25), (0.40, p40), (0.50, med)):
            j = int(q * (n - 1))
            if j >= z:
                val = lst[j - z]
                if val:
                    tgt[k] = val
        cmn[k] = lst[0]
        s1 = 0.0; s2 = 0.0
        for v in lst:
            s1 += v; s2 += v * v
        mu = s1 / n
        var = s2 / n - mu * mu
        sd[k] = var ** 0.5 if var > 0 else 0.0
    _H["p10"] = p10; _H["p25"] = p25; _H["p40"] = p40
    _H["med"] = med; _H["std"] = sd; _H["cmin"] = cmn


def _cal_update(base):
    """闭环校准: 昨日实发量 base 对上**策略自己昨天报出的当日水位** pwd, 得到低报/高报倍率。

    这是策略在决策时就能独立算出来的量(自己的输出 + ctx 免费给的昨日已实现需求),
    不依赖任何私有真值。逐 SKU 倍率 rat 做 EWMA 平滑, 另有一路全局总量倍率 grat
    刻画「昨天整体报少了还是报多了」。cal_b / gcal_b = 0 时下游不读这两路。
    """
    pwd = _H["pwd"]
    if not pwd:
        return
    lam = P["cal_lam"]
    lo, hi = P["cal_lo"], P["cal_hi"]
    rat = _H["rat"]
    sa = sw = 0.0
    for k, wv in pwd.items():
        if wv <= 0:
            continue
        av = base.get(k, 0.0)
        sa += av; sw += wv
        r = av / wv
        if r < lo:
            r = lo
        elif r > hi:
            r = hi
        rat[k] = lam * rat.get(k, 1.0) + (1.0 - lam) * r
    if sw > 0:
        g = sa / sw
        glo, ghi = P["gcal_lo"], P["gcal_hi"]
        if g < glo:
            g = glo
        elif g > ghi:
            g = ghi
        _H["grat"] = lam * _H["grat"] + (1.0 - lam) * g


def policy(ctx):
    w = int(ctx.get("w", 0) or 0)
    if _ST["pw"] is None or w <= _ST["pw"]:      # 新的一天(窗序号回卷)
        _H["pwd"] = _ST.get("wd") or {}          # 收走昨天自报的当日水位(各窗最大)
        _ST["mx"] = {}; _ST["base"] = None; _ST["psh"] = {}; _ST["prem"] = {}
        _ST["fi"] = {}; _ST["la"] = {}; _ST["hdone"] = False; _ST["lv"] = {}
        _ST["wd"] = {}; _ST["epsd"] = set()
        _ST["cday"] = []; _ST["cset"] = set()
    _ST["pw"] = w
    mxall = _ST["mx"]

    F = {}
    for n in ['P', 'air', 'asrs_age', 'asrs_box', 'box_age', 'dps_next', 'dps_today', 'ess', 'n_orders', 'picked_prior', 'priority', 'prod_ahead', 'rem', 'rem_2nd', 'rem_bulk', 'rem_ds', 'rem_fd', 'rem_parcel', 's_ms', 'shipped_today', 'water_hist', 'weight']:
        F[n] = ctx.get(n) or {}
    cands = ctx.get("_window_skus") or []
    _H["seen"].update(cands)
    # 当日累计候选集: 各窗 _window_skus 的并集。快照是稀疏抽样(实测 07-28 末窗只剩
    # 173 个里的 108 个、07-29 只剩 163 里的 83), 但滚动最大值把这些 SKU 的特征全留着 ——
    # 末窗信息最全却看不见它们, 纯属抽样损失。cd_day=0 时整条通路关闭(逐位等价)。
    _cdl = _ST.setdefault("cday", []); _cst = _ST.setdefault("cset", set())
    for _k in cands:
        if _k not in _cst:
            _cst.add(_k); _cdl.append(_k)
    Pspec = F["P"]

    # ── 数据缺口的前值填充 ──
    # rem / rem_ds / rem_fd / rem_parcel / picked_prior / air / n_orders / priority / weight
    # 这几路需求信号只在 w=0/1/2 的快照里有, 从 w=3 起整列消失 —— 那是取数缺口, 不是
    # 「需求归零」。不填充的话晚窗只剩滚动最大值可用, DS/FD 份额、零包扣减、画像修正
    # 全部退化, 于是主档被迫压在早窗发力; 而 shipped_today 的日内增量要到 w>=3 才看得见,
    # 主档发在早窗就再也享受不到它。按「整列为空才回填上一份非空快照」填充, 恰好只补
    # 结构性缺口, 不会把「本窗确实降到 0」误当成缺失。
    if P["carry_gap"]:
        lv = _ST.setdefault("lv", {})
        for n in ['P', 'air', 'asrs_age', 'asrs_box', 'box_age', 'dps_next', 'dps_today', 'ess', 'n_orders', 'picked_prior', 'priority', 'prod_ahead', 'rem', 'rem_2nd', 'rem_bulk', 'rem_ds', 'rem_fd', 'rem_parcel', 's_ms', 'shipped_today', 'water_hist', 'weight']:
            if F[n]:
                lv[n] = F[n]
            elif n in lv:
                F[n] = lv[n]

    # ── 派生增量特征(只用当日当前及更早窗的快照) ──
    # shipped_today 是一路累计量。实测它在 w=0/1/2 三个窗上逐 SKU **完全相同**、从 w=3
    # 起才开始增长 —— 也就是说 w<=2 的取值就是「今天开工前」的基线, 减掉它才是本 SKU
    # 今天真正走掉的量。只取首窗做基线会漏掉后两个窗才进稀疏快照的 SKU(个别工作日
    # 首窗只覆盖 4 个 SKU, 到 w=2 才补齐到 78 个), 那些 SKU 的增量会被整段高估。
    # bs_w 控制基线的采集截止窗(首窗恒采, 之后并入 w<=bs_w 的窗)。
    shn = F["shipped_today"]
    if _ST["base"] is None:
        _ST["base"] = dict((k, float(v)) for k, v in shn.items())
    elif w <= P["bs_w"]:
        _b = _ST["base"]
        for k, v in shn.items():
            if k not in _b:
                _b[k] = float(v)
    bse = _ST["base"]
    if not _ST.get("hdone") and w >= P["bs_w"]:
        _ST["hdone"] = True
        # 「隔日重启」判据: 当天开工基线整体为 0 == 昨天一整天没发货(周日/停产)。
        # 这是决策时就能看见的运营状态, 不是日期指纹。隔日重启的工作日节奏明显不同:
        # 早窗需求揭示慢、shipped_today 的口径也更宽(实测这类日子 sh_inc 相对当日
        # 实发量高估到 3~4 倍), 因此三档各给一个独立的档位系数。
        _ST["idle"] = (sum(bse.values()) <= 0)
        _hist_update(bse)
    psh = _ST["psh"]; prm = _ST["prem"]
    remn = F["rem"]
    d_inc = {}; d_shd = {}; d_remd = {}; d_remdrop = {}
    for k, v in shn.items():
        v = float(v)
        t = v - bse.get(k, 0.0)
        if t > 0:
            d_inc[k] = t
        t = v - psh.get(k, 0.0)
        if t > 0:
            d_shd[k] = t
    for k, v in remn.items():
        t = float(v) - prm.get(k, 0.0)
        if t > 0:
            d_remd[k] = t
    for k, v in prm.items():
        t = v - float(remn.get(k, 0) or 0)
        if t > 0:
            d_remdrop[k] = t
    F["sh_inc"] = d_inc; F["sh_d"] = d_shd; F["rem_d"] = d_remd; F["rem_drop"] = d_remdrop
    _ST["psh"] = dict((k, float(v)) for k, v in shn.items())
    _ST["prem"] = dict((k, float(v)) for k, v in remn.items())

    # ── 「开工存量」与「日内增量」的分离 ──
    # 当日首次出现该字段时的取值 = 今天开工前就压在那儿的存量(隔夜积压/未来批次),
    # 之后涨上来的部分才是今天新揭示、今天要发的量。实测同一个 SKU 的
    # rem 首见值兑现率很低(个别工作日只有 0.18~0.47), 而 rem 的日内增量兑现率
    # 高达 0.86~1.00 —— 两者必须分开定价, 不能只看一个总量。
    # 另一路: 现货/ESS/投料前瞻在日内的**下降量**是「今天确实流出去了多少」的直接证据。
    FI = _ST["fi"]; LA = _ST["la"]
    for n in DELTA:
        d = F[n]
        if not d:
            continue
        fi = FI.setdefault(n, {}); la = LA.setdefault(n, {})
        for k, v in d.items():
            v = float(v)
            if k not in fi:
                fi[k] = v
            la[k] = v
    for n, nm_f, nm_i, sign in DELTA_SPEC:
        fi = FI.get(n, {}); la = LA.get(n, {})
        gf = {}; gi = {}
        for k, v in fi.items():
            if v > 0:
                gf[k] = v
            t = (la.get(k, 0.0) - v) * sign
            if t > 0:
                gi[k] = t
        F[nm_f] = gf; F[nm_i] = gi

    for n in ROLL:                                # 当日滚动最大值
        d = F[n]
        if not d:
            continue
        m = mxall.setdefault(n, {})
        for k, v in d.items():
            v = float(v)
            if v > m.get(k, 0.0):
                m[k] = v

    # 跨日历史特征(当日内恒定, 不参与滚动最大)。放在 ROLL 之后注入, 避免被当成日内信号。
    F["h_lag"] = _H["lag"]; F["h_ewm"] = _H["ewm"]; F["h_mx"] = _H["mx"]
    F["h_frq"] = _H["frq"]; F["h_avg"] = _H["avg"]
    F["h_p10"] = _H["p10"]; F["h_p25"] = _H["p25"]; F["h_p40"] = _H["p40"]
    F["h_med"] = _H["med"]; F["h_std"] = _H["std"]; F["h_cmin"] = _H["cmin"]

    def cur(n, k):
        return float(F[n].get(k, 0) or 0)

    def rmax(n, k):
        m = mxall.get(n)
        if m is None:                 # 不做日内滚动的字段(跨日历史特征)直接取当前值
            return float(F.get(n, {}).get(k, 0) or 0)
        return float(m.get(k, 0.0))

    # 逐 SKU 循环里的 cur(n,k)/rmax(n,k) 每次都要先查一遍 n 再查 k。特征字典本身在
    # 一个窗内是固定的, 提到循环外只留 k 的那一次查表 —— 纯提速, 取值逐位不变
    # (字段值都是 float, `float(v or 0)` 与 `.get(k, 0.0)` 恒等)。
    def _cd(n):                       # cur 的特征字典
        return F[n]

    def _md(n):                       # rmax 的特征字典
        m = mxall.get(n)
        return F.get(n, {}) if m is None else m

    _R_s_ms = _md("s_ms")
    _R_asrs_box = _md("asrs_box")
    _R_rem = _md("rem")
    _R_rem_bulk = _md("rem_bulk")
    _R_water_hist = _md("water_hist")
    _R_rem_f = _md("rem_f")
    _R_rem_up = _md("rem_up")
    _C_s_ms = _cd("s_ms")
    _C_asrs_box = _cd("asrs_box")
    _C_dps_today = _cd("dps_today")
    _C_picked_prior = _cd("picked_prior")
    _C_rem_parcel = _cd("rem_parcel")
    _C_n_orders = _cd("n_orders")
    _C_asrs_age = _cd("asrs_age")
    _C_box_age = _cd("box_age")
    _C_priority = _cd("priority")

    rem = F["rem"]
    sms = F["s_ms"]
    remx = mxall.get("rem", {})

    # ───────── 码板整形的「保留价值」权重 ─────────
    # 码板额度(单窗 5760 箱)是紧约束, _pal_trim 每窗都真的在摘 SKU。原来只按码板成本
    # 排序, 等于默认「所有 SKU 一样值钱」。这里给每个 SKU 算一个保留价值权重 w_k,
    # 摘除序改成按 码板成本/w_k 从大到小 —— 同样的码板额度先留给最可能真出货的 SKU。
    # 全部系数为 0 时 w_k 恒等于 1, 走 tvw=None 的老通路, 与加这条通路之前逐位等价。
    _TP = P["tp"]
    if _TP:
        _tp_c = P["tp_c"]; _tp_lo = P["tp_lo"]
        _tp_q = _TP.get("q", 0.0); _tp_pk = _TP.get("pk", 0.0)
        _tp_sms = _TP.get("sms", 0.0); _tp_rem = _TP.get("rem", 0.0)
        _tp_si = _TP.get("si", 0.0); _tp_frq = _TP.get("frq", 0.0)
        _tp_ewm = _TP.get("ewm", 0.0); _tp_lag = _TP.get("lag", 0.0)
        _tp_hmx = _TP.get("hmx", 0.0); _tp_pp = _TP.get("pp", 0.0)
        _tp_no = _TP.get("no", 0.0); _tp_bage = _TP.get("bage", 0.0)
        _tp_aage = _TP.get("aage", 0.0); _tp_wh = _TP.get("wh", 0.0)
        _tp_asb = _TP.get("asb", 0.0); _tp_pcl = _TP.get("pcl", 0.0)
        # 当日水位取各窗最大 => 摘掉一个今天已经报过 wd_k 的 SKU, 真正丢掉的只是
        # **增量** max(0, q - wd_k), 而不是整个 q; wd_k=0 的才是「今天头一回报」,
        # 摘掉它还要额外赔一个命中。dq/wd/new 三路就是这件事的显式表达。
        _tp_dq = _TP.get("dq", 0.0); _tp_wd = _TP.get("wd", 0.0)
        _tp_new = _TP.get("new", 0.0); _tp_ess = _TP.get("ess", 0.0)
        _tp_pa = _TP.get("pa", 0.0); _tp_dps = _TP.get("dps", 0.0)
        _H_frq = _H["frq"]; _H_ewm = _H["ewm"]; _H_lag = _H["lag"]; _H_mx = _H["mx"]
        _tv_wd = _ST["wd"]; _C_ess = _cd("ess"); _C_pa = _cd("prod_ahead")

        def _tvw0(k, q):
            v = 1.0 + _tp_c
            if _tp_q:
                v += _tp_q * q / 12.0
            if _tp_pk:
                v += _tp_pk * (_pack(Pspec.get(k)) / 10.0 - 1.0)
            if _tp_sms:
                v += _tp_sms * sms.get(k, 0.0) / 12.0
            if _tp_rem:
                v += _tp_rem * remx.get(k, 0.0) / 13.0
            if _tp_si:
                v += _tp_si * d_inc.get(k, 0.0) / 20.0
            if _tp_frq:
                v += _tp_frq * _H_frq.get(k, 0.0)
            if _tp_ewm:
                v += _tp_ewm * _H_ewm.get(k, 0.0) / 20.0
            if _tp_lag:
                v += _tp_lag * _H_lag.get(k, 0.0) / 20.0
            if _tp_hmx:
                v += _tp_hmx * _H_mx.get(k, 0.0) / 25.0
            if _tp_pp:
                v += _tp_pp * _C_picked_prior.get(k, 0.0) / 12.0
            if _tp_no:
                v += _tp_no * _C_n_orders.get(k, 0.0) / 2.0
            if _tp_bage:
                v += _tp_bage * _C_box_age.get(k, 0.0) / 5.0
            if _tp_aage:
                v += _tp_aage * _C_asrs_age.get(k, 0.0) / 16.0
            if _tp_wh:
                v += _tp_wh * _R_water_hist.get(k, 0.0) / 26.0
            if _tp_asb:
                v += _tp_asb * _C_asrs_box.get(k, 0.0) / 105.0
            if _tp_pcl:
                v += _tp_pcl * _C_rem_parcel.get(k, 0.0) / 20.0
            if _tp_dq or _tp_wd or _tp_new:
                _b = _tv_wd.get(k, 0.0)
                if _tp_dq:
                    v += _tp_dq * (q - _b if q > _b else 0.0) / 12.0
                if _tp_wd:
                    v += _tp_wd * _b / 12.0
                if _tp_new and _b <= 0.0:
                    v += _tp_new
            if _tp_ess:
                v += _tp_ess * _C_ess.get(k, 0.0) / 22.0
            if _tp_pa:
                v += _tp_pa * _C_pa.get(k, 0.0) / 26.5
            if _tp_dps:
                v += _tp_dps * _C_dps_today.get(k, 0.0) / 5.0
            return v if v > _tp_lo else _tp_lo

        def _tvm(mult):
            # 同一套价值向量, 四个 trim 调用点各自一个强度(1.0 = 原样, 逐位等价)。
            if mult == 1.0:
                return _tvw0

            def _f(k, q):
                v = 1.0 + mult * (_tvw0(k, q) - 1.0)
                return v if v > _tp_lo else _tp_lo
            return _f

        _tvw = _tvw0
        _tvw_main = _tvm(P["tp_m_main"]); _tvw_fb = _tvm(P["tp_m_fb"])
        _tvw_ts = _tvm(P["tp_m_ts"]); _tvw_fin = _tvm(P["tp_m_fin"])
    else:
        _tvw = None
        _tvw_main = _tvw_fb = _tvw_ts = _tvw_fin = None

    wm = P["wm"][w]
    lwm = P["lwm"][w]
    # ── 逐窗机制强度(v46) ── 六窗取上包络 = 六个模型, 每层机制的松紧逐窗可调。
    _flw = P["flw"][w]; _clw = P["clw"][w]; _lfw = P["lfw"][w]; _lcw = P["lcw"][w]
    _tsw = P["tsw"][w]; _sfw = P["sfw"][w]; _scw = P["scw"][w]; _epw = P["epw"][w]
    U = P["u"]; V = P["v"]; M = P["m"]; FL = P["fl"]; CL = P["cl"]
    FL_ON = P["fl_on"] and bool(FL); CL_ON = P["cl_on"] and bool(CL)
    mlo, mhi = P["mlo"], P["mhi"]
    gu_lo = P["gu_lo"]; gu_p = P["gu_p"]; gp_lo = P["gp_lo"]; gp_p = P["gp_p"]
    sh_p = P["sh_p"]
    si_fl = P["si_fl"]; si_cl = P["si_cl"]; si_cl0 = P["si_cl0"]
    si_on = (si_fl > 0 or si_cl > 0) and w >= P["si_w"]
    si_rmx = P.get("si_rmx", 0.0) >= 0.5
    share_max = P["share_max"]

    # ───────── 主档 ─────────
    _q_remf = _md("rem_f"); _q_remup = _md("rem_up")
    _q_bulkf = _md("bulk_f"); _q_bulkup = _md("bulk_up")
    _q_pp = _cd("picked_prior"); _q_sht = _cd("shipped_today"); _q_par = _cd("rem_parcel")
    _q_rds = _md("rem_ds"); _q_rfd = _md("rem_fd")
    _q_cds = _cd("rem_ds"); _q_cfd = _cd("rem_fd")
    _q_sinc = _md("sh_inc")
    # ── 逐窗「信谁」权重 ──
    # 当日水位取六窗最大 => 六个窗其实是六个独立模型, 最后取上包络。原来六个窗共用
    # 同一组系数、只差一个整体倍率 wm[w], 那是同一个模型缩放六次, 取最大没有任何
    # 多样性增益。这里让「本窗值」(_a_cur / U 块)与「当日滚动最大值」(_a_max / V 块)
    # 的相对权重逐窗可调: 早窗滚动历史还没攒起来、该信本窗值, 晚窗反过来。
    # 六个窗于是成为**有差异**的模型, 取最大才真的是集成。全 1.0 时逐位等价。
    _acw = P["acw"][w]; _amw = P["amw"][w]; _uww = P["uww"][w]; _vww = P["vww"][w]
    _UL = [(_cd(n), c * _uww, SC[n]) for n, c in U.items() if c]
    _VL = [(_md(n), c * _vww, SC[n]) for n, c in V.items() if c]
    _ML = [(_cd(n), c, SC[n]) for n, c in M.items() if c]
    _FLL = [(_md(n), c) for n, c in FL.items()]
    _CLL = [(_md(n), c) for n, c in CL.items()]
    _a_cur = P["a_cur"] * _acw; _a_max = P["a_max"] * _amw
    _a_f = P["a_f"]; _a_up = P["a_up"]
    _a_bf = P["a_bf"]; _a_bup = P["a_bup"]; _a_par = P["a_par"]
    _a_pp = P["a_pp"]; _a_pp_sh = P["a_pp_sh"]
    _m_ds = P["m_ds"]; _m_sto = P["m_sto"]
    _fl_const = P["fl_const"]; _cl_const = P["cl_const"]
    main = {}
    _mcand = cands
    if P.get("cd_day", 0.0) >= 0.5 and w >= int(round(P.get("cd_w", 5.0))):
        _mcand = _ST["cday"]
    main = {}
    for k in _mcand:
        rc = float(rem.get(k, 0) or 0)
        rm = float(remx.get(k, 0.0))
        if rm <= 0:
            continue
        # 开工存量 rem_f 与日内新揭示 rem_up 分开定价(兑现率差一个数量级)
        rv = (_a_cur * rc + _a_max * rm
              + _a_f * _q_remf.get(k, 0.0) + _a_up * _q_remup.get(k, 0.0)
              + _a_bf * _q_bulkf.get(k, 0.0) + _a_bup * _q_bulkup.get(k, 0.0))
        pp = _q_pp.get(k, 0.0)
        app = _a_pp_sh if _q_sht.get(k, 0.0) > 0 else _a_pp
        r = rv - _a_par * _q_par.get(k, 0.0) - app * pp
        if r <= 0:
            continue
        den = rc if rc > 0 else rm
        # DS/FD 份额: rem_ds / rem_fd 只在 w<=2 的快照里有, 从 w=3 起整列消失, 于是晚窗
        # share 恒为 0、所有 SKU 一律吃 STO 的低系数 —— 这是取数缺口造成的误判, 不是
        # 「这个 SKU 变成纯 STO 了」。share_max 改用当日滚动最大值算份额, 让晚窗保持
        # 与早窗一致的 DS/STO 归类(只改分类, 不改量)。
        if share_max:
            dsv = _q_rds.get(k, 0.0) + _q_rfd.get(k, 0.0)
            dnm = rm if rm > 0 else den
        else:
            dsv = _q_cds.get(k, 0.0) + _q_cfd.get(k, 0.0)
            dnm = den
        share = min(1.0, dsv / dnm) if dnm > 0 else 0.0
        if sh_p != 1.0 and share > 0:
            share = share ** sh_p
        b = r * (_m_ds * share + _m_sto * (1.0 - share))
        if b < 0:
            b = 0.0
        if M:
            mm = 1.0
            for _d, c, _s in _ML:
                mm += c * _d.get(k, 0.0) / _s
            b *= min(mhi, max(mlo, mm))
        # 「开工存量 vs 日内新揭示」的份额折扣。实测同一 SKU 的 rem **首见值**兑现率
        # 只有 0.18~0.47(隔夜积压/未来批次, 今天多半不发), 而 rem 的**日内增量**兑现率
        # 高达 0.86~1.00。主档目前吃的是 rem 总量, 两种成色混在一起。这里按
        # share_up = 日内增量 /(日内增量 + 首见值) 做一个连续折扣: 全是新揭示的不打折,
        # 全是隔夜存量的打到 gu_lo。gu_lo=1 时整条通路关闭。
        if gu_lo < 1.0:
            _up = _q_remup.get(k, 0.0); _fi = _q_remf.get(k, 0.0)
            _t = _up + _fi
            if _t > 0:
                _sh = _up / _t
                q_mul = gu_lo + (1.0 - gu_lo) * (_sh ** gu_p)
            else:
                q_mul = gu_lo
            b *= q_mul
        # 零包份额折扣: 拆零需求不按整箱备水位, 份额越高越该压。
        if gp_lo < 1.0:
            _pa = _q_par.get(k, 0.0)
            if _pa > 0 and den > 0:
                _sp = _pa / den
                if _sp > 1.0:
                    _sp = 1.0
                b *= gp_lo + (1.0 - gp_lo) * ((1.0 - _sp) ** gp_p)
        q = wm * b
        for _d, c, _s in _UL:
            q += c * _d.get(k, 0.0) / _s
        for _d, c, _s in _VL:
            q += c * _d.get(k, 0.0) / _s
        # 下限: 「几乎必然会走掉」的那部分需求(整箱大货为主)托底 —— 只抬低估的 SKU,
        # 不动已经估准的 SKU, 所以不像加法项那样在准的地方制造浪费。
        if FL_ON:
            fl = _fl_const
            for _d, c in _FLL:
                fl += c * _d.get(k, 0.0)
            fl *= _flw
            if fl > q:
                q = fl
        # 上限: 用现货/立库/历史水位/投料等可动用量封顶, 压掉高估 SKU 的浪费。
        if CL_ON:
            cl = _cl_const
            for _d, c in _CLL:
                cl += c * _d.get(k, 0.0)
            cl *= _clw
            if cl >= 0 and q > cl:
                q = cl
        # 晚窗 sh_inc 校正: w>=3 起 shipped_today 开始增长, 其日内增量 sh_inc 是
        # 「这个 SKU 今天到此刻已经真的走掉多少」。实测把它整体当水位时, 精确率在
        # c=0.3~1.0 区间几乎不掉、FILL 却从 0.29 涨到 0.84, 到 c=1.25 精确率断崖 ——
        # 说明它非常接近当日实发量的一个紧下界。于是拿它给主档做「下托 + 上封」:
        # 已经走掉这么多的 SKU 水位不该更低(si_fl), 也不该比它高太多(si_cl)。
        if si_on:
            si = d_inc.get(k, 0.0)
            # shipped_today 是累计量, 其日内增量 sh_inc 逐窗单调不减; 但 SKU 掉出本窗
            # 稀疏快照时 d_inc 里就没有它了(末窗掉一半)。滚动最大值把这条证据补回来。
            if si_rmx:
                _sr = _q_sinc.get(k, 0.0)
                if _sr > si:
                    si = _sr
            if si > 0:
                if si_fl > 0:
                    t = si_fl * _sfw * si
                    if t > q:
                        q = t
                if si_cl > 0:
                    t = (si_cl * si + si_cl0) * _scw
                    if q > t:
                        q = t
        if q > 0:
            main[k] = q

    idle = _ST.get("idle", False)
    mo_main = P["mo_main"] if idle else 1.0
    mo_fb = P["mo_fb"] if idle else 1.0
    mo_ts = P["mo_ts"] if idle else 1.0
    # ── 冷启动档位 ──
    # 跨日历史(昨日实发的 EWMA/频次/峰值)要攒够天数才可信; 攒不够时 hf_/fb_hmin/
    # ts_hmin/gmul 这些历史通路要么退化、要么直接把 SKU 滤掉, 水位系统性偏低。
    # 「我手上攒了几天历史」和 idle 一样是决策时就看得见的运营状态(不是日期指纹),
    # 历史浅的日子整体给一个独立档位。cold_m=1.0 时逐位等价。
    if _H["days"] <= P["cold_d"]:
        _cm = P["cold_m"]
        mo_main *= _cm; mo_fb *= _cm; mo_ts *= _cm

    out = {}
    cap_abs = P["cap_abs"]; cap_rel = P["cap_rel"]; qmin = P["qmin"]
    for k, q in main.items():
        q *= mo_main
        if cap_rel > 0:
            avail = _C_s_ms.get(k, 0.0) + _C_asrs_box.get(k, 0.0) + _C_dps_today.get(k, 0.0)
            lim = cap_rel * avail
            if q > lim:
                q = lim
        if q > cap_abs:
            q = cap_abs
        if q > qmin:
            out[k] = q
    _pal_trim(out, sms, P["pal_cap"], _tvw_main)

    # ───────── 兜底档: 当日无任何剩余需求信号的候选 SKU ─────────
    # 这批 SKU 仍贡献可观的当日出货(实测个别工作日占全天出货件数 20%~32%),
    # 主档单独扛不过满足率线, 必须给它们一个保守水位。
    if lwm > 0:
        FB = P["fb"]; FBM = P["fbm"]
        fb_cap = P["fb_cap"]; fb_min = P["fb_min"]; fb_stk = P["fb_stk"]
        skip_rem = P["fb_skip_rem"]          # 兜底档是否也覆盖「有需求但被主档滤掉」的 SKU
        hmin = P["fb_hmin"]                  # 历史活跃度门槛: 历史上从没发过的 SKU 大概率是死货
        hfq = _H["frq"]; havg = _H["avg"]
        _FBL = [(_cd(n), c, SC[n]) for n, c in FB.items() if c]
        _FBML = [(_md(n), c, SC[n]) for n, c in FBM.items() if c]
        _fb_const = P["fb_const"]
        z = {}
        for k in cands:
            if k in out:
                continue
            if skip_rem and float(remx.get(k, 0.0)) > 0:
                continue
            if hmin > 0 and _H["days"] > 0 and hfq.get(k, 0.0) < hmin:
                continue
            q = _fb_const
            for _d, c, _s in _FBL:
                q += c * _d.get(k, 0.0) / _s
            for _d, c, _s in _FBML:
                q += c * _d.get(k, 0.0) / _s
            if q > 0:
                z[k] = q

        # 「预算式」兜底定量: 先用当日已揭示的各路聚合信号估一个当日出货体量 Dhat,
        # 再看主档已经备了多少件, 差额才交给兜底档去补。需求揭示得早、主档已经备足的
        # 工作日, 兜底档自动退到 0(不制造浪费); 需求迟迟不揭示的工作日, 兜底档自动放大
        # 去接住那部分「还没进 rem 就已经要发」的量。
        s = 1.0
        if P["bg_on"] and z:
            Dhat = 0.0
            for n, c in P["g"].items():
                if not c:
                    continue
                for k, v in mxall.get(n, {}).items():
                    Dhat += c * v * _pack(Pspec.get(k))
            Dhat *= P["bgw"][w]
            rmain = 0.0
            for k, q in out.items():
                rmain += q * _pack(Pspec.get(k))
            Z = 0.0
            for k, q in z.items():
                Z += q * _pack(Pspec.get(k))
            budget = P["theta"] * Dhat - rmain
            s = (budget / Z) if (Z > 1e-9 and budget > 0) else 0.0
            if s > P["bg_hi"]:
                s = P["bg_hi"]

        fb_sicl = P["fb_sicl"]
        fb = {}
        for k, q in z.items():
            q *= lwm * s * mo_fb
            if fb_sicl > 0:                   # 兜底档也吃 sh_inc 上封
                _si = d_inc.get(k, 0.0)
                if _si > 0 and q > fb_sicl * _si:
                    q = fb_sicl * _si
            if fb_stk > 0:                        # 备货不超过本 SKU 可动用量
                lim = fb_stk * (_C_s_ms.get(k, 0.0) + _C_asrs_box.get(k, 0.0))
                if q > lim:
                    q = lim
            if q > fb_cap:
                q = fb_cap
            if q > fb_min:
                fb[k] = q
        _pal_trim(fb, sms, P["fb_pal_cap"], _tvw_fb)
        out.update(fb)

    # ───────── S 档: 「今天在动、但整天没进 rem」的 SKU ─────────
    # rem 只覆盖 DS/FD/STO 已揭示需求; 有一批 SKU 整天 rem 都是 0, 却实实在在在出货
    # (实测个别工作日占当日出货件数 12%~25%)。shipped_today 相对当日首窗的增量
    # sh_inc 正是「这个 SKU 今天已经走掉多少」—— 用它给这批 SKU 补一个水位, 再用
    # 「本 SKU 现货 + 立库折箱」封顶(备货不可能超过实际能动用的量, 也顺带滤掉
    # shipped_today 口径偏宽带来的虚高)。只在较晚的决策窗启用: 早窗 sh_inc 还看不出
    # 谁在动, 过早补货纯属浪费; 当日水位取六窗最大, 晚窗补一次即可。
    ts_c = P["ts_c"]
    if ts_c > 0 and w >= P["ts_w"]:
        TS = P["ts"]; ts_stk = P["ts_stk"]; ts_cap = P["ts_cap"]; ts_min = P["ts_min"]
        ts_hmin = P["ts_hmin"]
        hfq2 = _H["frq"]
        ts = {}
        for k in cands:
            if float(remx.get(k, 0.0)) > 0:      # 有需求信号的走主档
                continue
            si = d_inc.get(k, 0.0)
            if si <= 0:
                continue
            if ts_hmin > 0 and _H["days"] > 0 and hfq2.get(k, 0.0) < ts_hmin:
                continue
            q = ts_c * _tsw * si * mo_ts
            for n, c in TS.items():
                if c:
                    q += c * rmax(n, k) / SC[n]
            if ts_stk > 0:
                lim = ts_stk * (_R_s_ms.get(k, 0.0) + _R_asrs_box.get(k, 0.0))
                if q > lim:
                    q = lim
            if q > ts_cap:
                q = ts_cap
            if si_cl > 0:                      # S 档同样吃 sh_inc 上封
                t = P["ts_sicl"] * si
                if t > 0 and q > t:
                    q = t
            if q > ts_min and q > out.get(k, 0.0):
                ts[k] = q
        _pal_trim(ts, sms, P["ts_pal_cap"], _tvw_ts)
        out.update(ts)

    # 「无信号档」缩量: 当日既没揭示过任何剩余需求(rem 滚动最大=0)、shipped_today 也
    # 一直没动(sh_inc=0)的 SKU, 切片消融实测其**边际精确率只有 0.178**, 远低于盈亏线
    # (FILL<0.7 的日子约 0.375, FILL>=0.7 的日子约 0.85)—— 是浪费的主要来源。
    # 但直接删掉会掉命中率(HIT 按 SKU 个数算, 每个 1.0 值 10 分/单位)。
    # 正解是**留一个象征性水位**: 命中率按 SKU 个数计、浪费率按件数计, 所以把量压到
    # 几个百分点就能既保住 HIT 又几乎不产生浪费件数。
    ns_mul = P["ns_mul"]
    if ns_mul < 1.0:
        for k in list(out):
            if float(remx.get(k, 0.0)) <= 0 and d_inc.get(k, 0.0) <= 0:
                out[k] *= ns_mul
    tail_thr = P["tail_thr"]
    if tail_thr > 0:
        tm = P["tail_mul"]
        for k in list(out):
            if out[k] < tail_thr:
                out[k] *= tm

    # ───────── 画像分组乘性修正 ─────────
    # 诊断(notes/v6/grpmarg.py): 把可观测子群的水位整体缩放, 逐日测边际精确率
    # Δsfill/Δsrec 并与盈亏线 p*=Prec²/(Prec+g·FILL) 比较, 发现若干子群系统性偏离:
    # 例如「本窗 picked_prior>0(已进拣货流程)」的 SKU 向下缩 0.75 的边际精确率
    # 只有 0.25~0.73, 普遍低于所在日的盈亏线 —— 说明这批还留着多余水位。
    # 主档虽然已经线性扣减 picked_prior, 但那是在封顶/托底之前, 扣不干净。
    # 这里在三档合并之后再加一层纯乘性的分组修正, 每组一个系数, 1.0 = 关闭。
    GMUL = P.get("gmul") or []
    if idle and P.get("gmi"):
        GMUL = list(GMUL) + list(P["gmi"])
    if GMUL:
        _sms0 = sms
        # 分组判据里的阈值原先是硬编码常数(1/2/5 箱、0.5x现货、2x已发、库龄 10/3)。
        # GM 层是灵敏度最高的一层(gmi_picked_prior/gmi_pp_nosi/gmi_q_lt2 是前三名),
        # 所以把这些切点本身也放进搜索空间 —— 默认值就是原常数, 逐位等价。
        _gq1 = P.get("gth_q1", 1.0); _gq2 = P.get("gth_q2", 2.0); _gq5 = P.get("gth_q5", 5.0)
        _ghs = P.get("gth_hsms", 0.5); _g2s = P.get("gth_ge2si", 2.0)
        _g2r = P.get("gth_ge2rem", 2.0); _gaa = P.get("gth_aage", 10.0)
        _gba = P.get("gth_bage", 3.0); _gn1 = P.get("gth_no1", 1.0)
        for k in list(out):
            mm = 1.0
            for n, c in GMUL:
                if c == 1.0:
                    continue
                if n == "remx0":
                    ok = _R_rem.get(k, 0.0) <= 0
                elif n == "pp_nosi":
                    ok = _C_picked_prior.get(k, 0.0) > 0 and d_inc.get(k, 0.0) <= 0
                elif n == "si_norem":
                    ok = d_inc.get(k, 0.0) > 0 and _R_rem.get(k, 0.0) <= 0
                elif n == "rem_nosi":
                    ok = _R_rem.get(k, 0.0) > 0 and d_inc.get(k, 0.0) <= 0
                elif n == "par_gt_rem":
                    ok = _C_rem_parcel.get(k, 0.0) > float(rem.get(k, 0) or 0)
                elif n == "w_lt_sms":
                    ok = out[k] < float(_sms0.get(k, 0) or 0)
                elif n == "sms0":
                    ok = float(_sms0.get(k, 0) or 0) <= 0
                elif n == "rem0":
                    ok = float(rem.get(k, 0) or 0) <= 0
                elif n == "si_pos":
                    ok = d_inc.get(k, 0.0) > 0
                elif n == "no1":
                    ok = _C_n_orders.get(k, 0.0) <= _gn1
                elif n == "bulk0_rem":
                    ok = _R_rem.get(k, 0.0) > 0 and _R_rem_bulk.get(k, 0.0) <= 0
                elif n == "q_lt1":
                    ok = out[k] < _gq1
                elif n == "q_lt2":
                    ok = out[k] < _gq2
                elif n == "q_lt5":
                    ok = out[k] < _gq5
                elif n == "q_lt_si":
                    ok = out[k] < d_inc.get(k, 0.0)
                elif n == "q_ge2si":
                    _s = d_inc.get(k, 0.0)
                    ok = _s > 0 and out[k] >= _g2s * _s
                elif n == "q_ge2rem":
                    _r = _R_rem.get(k, 0.0)
                    ok = _r > 0 and out[k] >= _g2r * _r
                elif n == "rem0_si0":
                    ok = _R_rem.get(k, 0.0) <= 0 and d_inc.get(k, 0.0) <= 0
                elif n == "rem_si":
                    ok = _R_rem.get(k, 0.0) > 0 and d_inc.get(k, 0.0) > 0
                elif n == "wh0":
                    ok = _R_water_hist.get(k, 0.0) <= 0
                elif n == "aage_hi":
                    ok = _C_asrs_age.get(k, 0.0) > _gaa
                elif n == "bage_hi":
                    ok = _C_box_age.get(k, 0.0) > _gba
                elif n == "q_lt_hsms":
                    ok = out[k] < _ghs * float(_sms0.get(k, 0) or 0)
                elif n == "q_lt_rem":
                    ok = out[k] < _R_rem.get(k, 0.0)
                else:
                    ok = cur(n, k) > 0
                if ok:
                    mm *= c
            if mm != 1.0:
                out[k] *= mm

    # ───────── 合并后的连续画像修正 ─────────
    # 与主档内部的乘性画像 M 同形, 但作用在**三档合并、封顶托底之后**的最终水位上,
    # 并额外吃几路比值特征(已拣份额/零包份额/已发份额/水位相对现货)。
    # 系数全 0 时整层关闭, 与加它之前逐位等价。
    PM = P.get("pm") or []
    if PM:
        pm_lo = P["pm_lo"]; pm_hi = P["pm_hi"]
        for k in list(out):
            q0 = out[k]
            mm = 1.0
            for n, c in PM:
                if n == "r_pp":
                    dn = _R_rem.get(k, 0.0) + 1.0
                    x = _C_picked_prior.get(k, 0.0) / dn
                elif n == "r_par":
                    dn = _R_rem.get(k, 0.0) + 1.0
                    x = _C_rem_parcel.get(k, 0.0) / dn
                elif n == "r_si":
                    dn = _R_rem.get(k, 0.0) + 1.0
                    x = d_inc.get(k, 0.0) / dn
                elif n == "r_qms":
                    x = q0 / (float(sms.get(k, 0) or 0) + 1.0)
                elif n == "r_msq":
                    x = float(sms.get(k, 0) or 0) / (q0 + 1.0)
                elif n == "r_rq":
                    x = _R_rem.get(k, 0.0) / (q0 + 1.0)
                elif n == "lq":
                    x = math.log1p(q0)
                elif n == "r_up":
                    dn = _R_rem_f.get(k, 0.0) + _R_rem_up.get(k, 0.0) + 1.0
                    x = _R_rem_up.get(k, 0.0) / dn
                else:
                    x = cur(n, k) / SC[n]
                mm += c * x
            if mm < pm_lo:
                mm = pm_lo
            elif mm > pm_hi:
                mm = pm_hi
            if mm != 1.0:
                out[k] = q0 * mm

    # ───────── 阈值分组乘性修正 + 合并后逐窗系数 ─────────
    # 三档合并后的水位再按「量级/现货/需求」几条阈值切分, 每段一个乘性系数;
    # 阈值本身可搜索。与 gmul 的 0/1 指示不同, 这里切的是连续量的分位。
    for _thn, _th, _mu in P.get("tg") or []:
        if _mu == 1.0:
            continue
        for k in list(out):
            if _thn == "q":
                x = out[k]
            elif _thn == "sms":
                x = float(sms.get(k, 0) or 0)
            elif _thn == "remx":
                x = _R_rem.get(k, 0.0)
            elif _thn == "wh":
                x = _R_water_hist.get(k, 0.0)
            else:
                x = rmax(_thn, k)
            if x > _th:
                out[k] *= _mu
    _pwm = P.get("pwm")
    if _pwm and _pwm[w] != 1.0:
        _m = _pwm[w]
        for k in list(out):
            out[k] *= _m

    # ───────── 日尺度松紧修正 ─────────
    # oracle 实测(notes/v5/oracle_alpha.py): 逐日最优整体倍率在 FILL 宽松的日子 <1、
    # 在紧的日子 >1, 上限约 +0.03 quality。判据必须是决策时可观测的日尺度聚合量:
    # rho_ms = Σ本窗现货(件) / Σ自报水位(件) —— 实测与「当日真实需求/自报水位」
    # 的相关系数达 -0.68(notes/v6/dayfeat.py), 是目前最强的日级松紧代理。
    dg_b = P.get("dg_b", 0.0); dg_c = P.get("dg_c", 0.0); dg_d = P.get("dg_d", 0.0)
    if (dg_b or dg_c or dg_d) and w >= P.get("dg_w", 0) and out:
        sp = 0.0; sm = 0.0; sw = 0.0; sr = 0.0
        for k, q in out.items():
            pk_ = _pack(Pspec.get(k))
            sp += q * pk_
            sm += float(sms.get(k, 0) or 0) * pk_
            sw += _R_water_hist.get(k, 0.0) * pk_
            sr += _R_rem.get(k, 0.0) * pk_
        if sp > 0:
            mul = P.get("dg_a", 1.0) + dg_b * (sm / sp) + dg_c * (sw / sp) + dg_d * (sr / sp)
            lo = P.get("dg_lo", 1.0); hi = P.get("dg_hi", 1.0)
            if mul < lo:
                mul = lo
            elif mul > hi:
                mul = hi
            if mul != 1.0:
                for k in list(out):
                    out[k] *= mul

    # ───────── 合并后的线性托底 / 封顶 ─────────
    # 主档内部的 FL/CL 只作用在「本窗有剩余需求」的 SKU 上; 这一层作用在三档合并之后,
    # 覆盖兜底档 / S 档给出的水位, 并且用的是当日滚动最大值(因果)。系数为空时整层关闭。
    PFL = P.get("pfl") or {}
    if PFL:
        _pflr = P.get("pfl_rec", True)
        for k in cands:
            cq = out.get(k, 0.0)
            if _pflr and cq <= 0:
                continue
            t = P.get("pfl_const", 0.0)
            for n, c in PFL.items():
                t += c * rmax(n, k)
            if t > cq:
                out[k] = t
    PCL = P.get("pcl") or {}
    if PCL:
        _c0 = P.get("pcl_const", 0.0)
        for k in list(out):
            t = _c0
            for n, c in PCL.items():
                t += c * rmax(n, k)
            if t >= 0 and out[k] > t:
                out[k] = t
    _mofin = P.get("mo_fin", 1.0)
    if idle and _mofin != 1.0:
        for k in list(out):
            out[k] *= _mofin

    # ───────── 日尺度「追赶」增益 ─────────
    # 问题诊断: 多条加水位的方向在 FILL 紧的日子边际精确率高达 0.96~1.00(远超盈亏线
    # 0.40), 却因为在 FILL 宽松的日子(盈亏线 0.86~0.92)同样加量而整体亏掉。
    # 也就是说缺的不是「加多少」, 而是**「今天该不该加」的判据**。
    # 这个判据在决策时就有: shipped_today 的日内增量 sh_inc 是当日实发量的紧下界,
    # 把它(件数)对上策略自己到此刻已报出的当日水位(件数), 比值就是「今天的实际节奏
    # 相对自己计划的倍数」。比值高 = 今天比计划忙, 计划报低了 —— 正是要追加的日子。
    # 当日水位取六窗最大, 所以晚窗放大只会抬不会降, 方向天然正确。
    rnd_on = P["rnd_on"]
    ct_g = P["ct_g"]
    if ct_g > 0 and w >= P["ct_w"] and out:
        _wdp = _ST["wd"]
        sp = 0.0
        for k, q in out.items():
            v = _wdp.get(k, 0.0)
            if q > v:
                v = q
            sp += v * _pack(Pspec.get(k))
        for k, v in _wdp.items():
            if k not in out:
                sp += v * _pack(Pspec.get(k))
        if sp > 0:
            si = 0.0
            for k, v in d_inc.items():
                si += v * _pack(Pspec.get(k))
            mul = 1.0 + ct_g * (si / sp - P["ct_th"])
            if mul > 1.0:
                if mul > P["ct_hi"]:
                    mul = P["ct_hi"]
                for k in out:
                    out[k] *= mul

    # ───────── 跨日历史的下托 / 上封 ─────────
    # 诊断: 当前解的件数精确率 0.91~0.99, 但推荐总量只有当日真实需求的 0.67~0.95 ——
    # 也就是「大部分 SKU 估得很准、少部分严重低估」。整体缩放救不了(实测边际精确率
    # 只有 0.28, 远低于 FILL<0.7 日子的盈亏线 0.41), 必须做**重分配**: 只抬低估的、
    # 只压高估的。跨日历史(昨日实发 / EWMA / 日均 / 历史峰值)正是每个 SKU 的量级先验,
    # 以 floor/cap 的形式加入, 不动已经估准的那部分。
    hf_c = P["hf_c"]; hc_c = P["hc_c"]
    if (hf_c > 0 or hc_c > 0) and w >= P["hf_w"] and _H["days"] > 0:
        HF = P["hf"]
        gate = P["hf_gate"]; hfrq = P["hf_frq"]; _frq = _H["frq"]
        hsrc = {}
        for n, c in HF.items():
            if not c:
                continue
            for k, v in F[n].items():
                if v > 0:
                    hsrc[k] = hsrc.get(k, 0.0) + c * v
        for k, hv in hsrc.items():
            if hv <= 0:
                continue
            if hfrq > 0 and _frq.get(k, 0.0) < hfrq:
                continue
            cq = out.get(k, 0.0)
            if hf_c > 0:
                if gate == 0:                      # 只抬已经在推荐里的 SKU
                    ok = cq > 0
                elif gate == 1:                    # 再加上「今天已经在动」的
                    ok = cq > 0 or d_inc.get(k, 0.0) > 0
                else:                              # 全部候选
                    ok = k in cands or cq > 0
                if ok:
                    t = hf_c * hv
                    if t > cq:
                        out[k] = cq = t
            if hc_c > 0 and cq > hc_c * hv:
                out[k] = hc_c * hv

    # ───────── 闭环校准: 用昨天的自评偏差修今天的水位 ─────────
    # rat_k = EWMA(昨日实发_k / 昨日自报水位_k), grat = EWMA(昨日实发总量 / 自报总量)。
    # 指数 cal_b / gcal_b 控制施加强度(0=关)。当日水位取六窗最大, 所以 cal_w 若设在
    # 晚窗, 这条通路只会**抬**不会降 —— 抬低估、留准的, 正是需要的方向。
    cal_b = P["cal_b"]; gcal_b = P["gcal_b"]
    if (cal_b > 0 or gcal_b > 0) and w >= P["cal_w"] and _H["days"] > 0:
        gm = _H["grat"] ** gcal_b if gcal_b > 0 else 1.0
        if cal_b > 0:
            rat = _H["rat"]
            for k in list(out):
                r = rat.get(k)
                out[k] *= gm * ((r ** cal_b) if r and r > 0 else 1.0)
        elif gm != 1.0:
            for k in list(out):
                out[k] *= gm

    # rem_2nd(第二批次剩余需求)托底: 实测把它的当日滚动最大值单独当水位时,
    # c<=1.0 区间精确率恒为 1.000(c=1.5 才掉到 0.970)—— 也就是说它是当日实发量的一个
    # **严格下界**。把水位托到它上面不会产生任何浪费, 反而做大了浪费率的分母、
    # 同时抬满足率, 是纯赚的一笔。量不大(约占全天出货件数 1.8%), 但零成本。
    r2 = P["r2_fl"]
    LBF = P["lbf"]
    if r2 > 0 or LBF:
        m2 = mxall.get("rem_2nd", {})
        _lbf_ord = P.get("lbf_ord", 1.0)
        _LBFL = [(_md(_n), _c) for _n, _c in LBF.items()]
        lbf_rec = P["lbf_rec"]        # 只抬「已经在推荐里」的 SKU: 抬水位反而降码板,
        for k in cands:               # 而**新拉进推荐集**要付 max(0, 现货-水位) 的码板,
            cq = out.get(k, 0.0)      # 在码板已经吃满的状态下会顶掉一批 ε 覆盖。
            if lbf_rec and cq <= 0:
                continue
            t = r2 * m2.get(k, 0.0)
            t2 = t                       # 次大值: max 形对单路噪声很敏感, 用
            for _d, _c in _LBFL:         # ord*max1+(1-ord)*max2 做鲁棒化(ord=1 即原式)
                v = _c * _d.get(k, 0.0)
                if v > t:
                    t2 = t; t = v
                elif v > t2:
                    t2 = v
            if _lbf_ord < 1.0:
                t = _lbf_ord * t + (1.0 - _lbf_ord) * t2
            t *= _lfw
            if t > cq:
                out[k] = t

    # ───────── 合并后的 min 形上封(与上面 lbf 的 max 形下托对称)─────────
    # lbf 取若干「当日实发量下界」里最松的一条托底; 这里取若干「上界」里最紧的一条压顶。
    # 与 pcl(线性求和封顶)的区别和 lbf 与 pfl 的区别一样: min 形只在**某一路信号单独
    # 就说不通**时才发火, 不会因为几路信号各贡献一点点而误伤估准了的 SKU。
    # 系数 0 = 该项不参与; 封顶值 <=0 时不生效 —— 不会把 SKU 压出推荐集, 保住 HIT。
    LBC = P.get("lbc") or {}
    if LBC:
        _lbo = P.get("lbc_off", 0.0)
        _lbc_ord = P.get("lbc_ord", 1.0)
        _LBCL = [(_md(_n), _c) for _n, _c in LBC.items()]
        for k in list(out):
            cq = out[k]
            t = None; t2 = None          # 次小值: 同理做 min 形的鲁棒化(ord=1 即原式)
            for _d, _c in _LBCL:
                v = _c * _d.get(k, 0.0) + _lbo
                if t is None or v < t:
                    t2 = t; t = v
                elif t2 is None or v < t2:
                    t2 = v
            if t is not None:
                if _lbc_ord < 1.0 and t2 is not None:
                    t = _lbc_ord * t + (1.0 - _lbc_ord) * t2
                t *= _lcw
                if 0.0 < t < cq:
                    out[k] = t

    # ───────── 水位取整 ─────────
    # ACT 是整箱数, 所以最优水位也是整数。实测约七成推荐件数落在「水位刚好比实发量高
    # 一点点」的 SKU 上 —— 把小数部分抹掉正好削掉那部分浪费, 而对水位低于实发量的
    # SKU 只损失不到一箱。取整后为 0 的保持原值, 免得把 HIT 一起抹掉。
    if rnd_on:
        rnd_off = P["rnd_off"]
        _RNB = P.get("rnb")          # v50: 取整偏置按水位量级分桶(全 0 => 逐位等价)
        _qmc = P["qmc"]
        for k in list(out):
            v = out[k]
            if v >= 1.0:
                _off = rnd_off
                if _RNB:
                    _off += _RNB[_cbk(v, _qmc)]
                    if _off < 0.0:
                        _off = 0.0
                    elif _off > 1.0:
                        _off = 1.0
                t = float(int(v + _off))
                if t > 0:
                    out[k] = t

    # ───────── 因果「运行最大值」过滤 ─────────
    # 当日水位 = 各窗最大、推荐集 = 各窗并集。所以一个 SKU 只要在今天更早的窗里已经
    # 报过 >= 本窗值的水位, 本窗再报一遍**不改变任何被评估的量**, 却要再付一遍单窗
    # 码板成本 max(0, 现货−水位)。把这批重复申报撤掉, 逐窗码板量立刻掉一大截
    # (实测 07-18 5519→3122、07-29 2444→838), 腾出的码板预算让给 ε 档铺覆盖面、
    # 也让 pal_trim 少摘 SKU。rmx_tol=0 时整条通路关闭(与关闭前逐位等价)。
    # rmx_eps>=0.5: 撤掉的 SKU 同时登记进 ε 档的「已覆盖」集合。否则它们立刻变成 ε 档的
    # 合格候选被重新报一遍 eps_c —— 而 eps_c 比原值小得多, 码板成本 max(0, 现货−水位)
    # 反而**更贵**, 撤销白撤。这一步是 rmx 通路能不能真省下码板预算的关键。
    _rt = P.get("rmx_tol", 0.0)
    if _rt > 0:
        _wdr = _ST["wd"]
        _rse = P.get("rmx_eps", 0.0) >= 0.5
        _epd = _ST["epsd"]
        # rmx_tol > 1 是在**拿水位换码板额度**: 本窗值虽然比今日已报最大值高(能抬当日
        # 水位), 但只高了不到 rmx_tol 倍就干脆不报, 省下 max(0, 现货-水位) 的码板。
        # 这个取舍对每个 SKU 显然不一样 —— 现货巨大的 SKU 码板很贵、该狠狠地撤;
        # 现货很小的 SKU 撤了也省不下什么、白丢水位。所以门槛按 SKU 缩放:
        #   门槛_k = rmx_tol * (1 + rx_c + Σ rx_n·特征_n/尺度_n)
        # 系数全 0 时走下面的标量老通路, 与加这条通路之前逐位等价。
        _RX = P["rx"]
        if _RX:
            _rx_c = P["rx_c"]; _rx_lo = P["rx_lo"]
            _rx_sms = _RX.get("sms", 0.0); _rx_q = _RX.get("q", 0.0)
            _rx_rat = _RX.get("rat", 0.0); _rx_rem = _RX.get("rem", 0.0)
            _rx_si = _RX.get("si", 0.0); _rx_frq = _RX.get("frq", 0.0)
            _rx_pk = _RX.get("pk", 0.0); _rx_pp = _RX.get("pp", 0.0)
            _rx_ewm = _RX.get("ewm", 0.0); _rx_no = _RX.get("no", 0.0)
            _rxH_frq = _H["frq"]; _rxH_ewm = _H["ewm"]
            for _k in list(out):
                _pm = _wdr.get(_k, 0.0)
                if _pm <= 0:
                    continue
                _q = out[_k]
                _f = 1.0 + _rx_c
                if _rx_sms:
                    _f += _rx_sms * sms.get(_k, 0.0) / 12.0
                if _rx_q:
                    _f += _rx_q * _q / 12.0
                if _rx_rat:
                    _f += _rx_rat * (_q / _pm)
                if _rx_rem:
                    _f += _rx_rem * remx.get(_k, 0.0) / 13.0
                if _rx_si:
                    _f += _rx_si * d_inc.get(_k, 0.0) / 20.0
                if _rx_frq:
                    _f += _rx_frq * _rxH_frq.get(_k, 0.0)
                if _rx_pk:
                    _f += _rx_pk * (_pack(Pspec.get(_k)) / 10.0 - 1.0)
                if _rx_pp:
                    _f += _rx_pp * _C_picked_prior.get(_k, 0.0) / 12.0
                if _rx_ewm:
                    _f += _rx_ewm * _rxH_ewm.get(_k, 0.0) / 20.0
                if _rx_no:
                    _f += _rx_no * _C_n_orders.get(_k, 0.0) / 2.0
                if _f < _rx_lo:
                    _f = _rx_lo
                if _q <= _pm * (_rt * _f):
                    del out[_k]
                    if _rse:
                        _epd.add(_k)
        else:
            for _k in list(out):
                _pm = _wdr.get(_k, 0.0)
                if _pm > 0 and out[_k] <= _pm * _rt:
                    del out[_k]
                    if _rse:
                        _epd.add(_k)

    # ───────── ε 档: 用「量纲不对称」白捡命中率 ─────────
    # HIT = |推荐 ∩ 有需求| / |有需求|, 按 **SKU 个数** 算; WASTE/FILL 按 **件数** 算。
    # 所以给一个候选 SKU 一个极小水位, 命中率上算满一个, 浪费率上只加零点几件。
    # 实测每天有 1~21 个「确实出了货、但被三档全滤掉」的 SKU 就在候选集里(07-23 一天 21 个)。
    # 唯一的真实代价是码板: 水位低于现货, 差额要码板回立库, 单窗上限 5760 箱。因此按
    # 本窗现货 s_ms 升序贪心加(先加现货少的, 码板最便宜), 加到预算 eps_pal 用完为止。
    # 当日水位取六窗最大、推荐集是六窗并集 —— 每窗只加得起一部分, 靠错峰也能摊开覆盖面。
    eps_c = P["eps_c"]; eps_pal = P["eps_pal"]
    if eps_c > 0 and eps_pal > 0 and w >= P["eps_w"]:
        room = eps_pal * _epw
        for k, q in out.items():
            t = float(sms.get(k, 0) or 0) - q
            if t > 0:
                room -= t
        if room > 0:
            smax = P["eps_smax"]; nmax = P["eps_n"]; sfull = P["eps_sfull"]
            # 已经在今天更早的窗里 ε 覆盖过的 SKU 不必再报: 推荐集是六窗并集、当日水位
            # 取六窗最大, 所以重复报一次拿不到任何新东西, 却要再付一遍码板成本。
            # 跳过它们等于把预算全部让给「还没覆盖到」的 SKU —— 同样的码板预算,
            # 六个窗滚下来能摊开的覆盖面成倍增加。
            epsd = _ST["epsd"]
            once = P["eps_once"]
            pf = P["eps_pf"]; pk_ = P["eps_pk"]
            hfq3 = _H["frq"]
            # 候选池: 本窗候选 ∪(历史上出过货 / 历史上见过的 SKU)。
            # 稀疏快照每天只列出一部分 SKU, 但「昨天发过货」的 SKU 今天照样可能发 ——
            # 每天仍有 1~9 个实际出货的 SKU 整天没进过任何一窗 _window_skus。给这批
            # 历史活跃 SKU 一个常备的极小水位是合理的运营动作, 而且它们不在本窗现货
            # 快照里, 码板成本恰好为 0(pal = max(0, s_ms−水位), s_ms 缺省即 0)。
            uni = P["eps_uni"]
            if uni == 0:
                src_pool = cands
            else:
                src_pool = list(cands)
                seen_c = set(cands)
                # ★池子一律 ⊆ 当日累计候选集 _cdl: 逐窗快照是稀疏抽样, 同一 SKU
                #   w=1 在册、w=5 就不在册; 它今天确实进过候选清单, 在晚窗给它常备
                #   极小水位与在早窗给完全等价(当日水位取六窗最大), 仍在「本窗允许
                #   推荐范围」的语义内。而跨日 _H["seen"]/_H["frq"] 里今天没进过任何
                #   一窗候选清单的 SKU 不能推(越界), 也不该白占 eps_n 预算。
                for k in _cdl:
                    if k in seen_c:
                        continue
                    # uni==1: 只补「历史上出过货」的; uni==2: 当日候选全补。
                    if uni == 1 and hfq3.get(k, 0.0) <= 0:
                        continue
                    src_pool.append(k)
            pool = []
            for k in src_pool:
                if k in out:
                    continue
                if once and k in epsd:
                    continue
                sv = float(sms.get(k, 0) or 0)
                # 现货本来就少的 SKU: 直接把水位顶到现货, 码板成本恰好为 0(不占预算),
                # 浪费也只有几箱 —— 这批可以不受预算限制地全加。
                if 0.0 < sv <= sfull:
                    out[k] = sv
                    epsd.add(k)
                    continue
                if smax > 0 and sv > smax:
                    continue
                # 排序键 = 码板成本 / 命中收益。收益先验用跨日出货频次(纯历史, 因果),
                # 预算紧的日子优先覆盖「历史上经常出货」的 SKU。
                gain = 1.0 + pf * hfq3.get(k, 0.0)
                pool.append(((sv + pk_) / gain, sv, k))
            pool.sort()
            n = 0
            for _pri, sv, k in pool:
                c = sv - eps_c
                if c < 0:
                    c = 0.0
                if c > room:
                    continue
                out[k] = eps_c
                epsd.add(k)
                room -= c
                n += 1
                if nmax > 0 and n >= nmax:
                    break

    # ───────── 板规分组末端倍率 ─────────
    # P(板规)是唯一一列「决策时看得见、却几乎没被用来做判别」的 SKU 静态画像。
    # 不同板规 ≈ 不同品类/包装形态, 出货节奏本就不同, 给每组一个独立激进度。
    # 倍率恰为 1.0 的组不进 P["pgm"], 表为空时整条通路关闭(与加它之前逐位等价)。
    # 倍率 0 = 该板规整组不报(水位 <=0 的 SKU 评估器直接跳过, 不进推荐集)。
    _PGM = P["pgm"]
    if _PGM:
        for _k in list(out):
            _pv = Pspec.get(_k)
            if not _pv:
                continue
            try:
                _m = _PGM.get(int(round(float(_pv))))
            except (TypeError, ValueError):
                continue
            if _m is not None:
                out[_k] = out[_k] * _m

    # ───────── 其余画像分桶末端倍率 ─────────
    # 与 pgm 同形。密度排名(非零 (sku,窗) 对)里 box_age 8933 排第四, n_orders 1966、
    # priority 1915 紧随其后, 而它们此前都只以线性项 + 至多一个硬阈值出现 —— 分桶
    # 给出**分段常数**形状, 非单调的规律也能表达。rqs/rqw 切的是「当前水位/箱库现货」
    # 「当前水位/历史水位」两条比值的分位: 前者衡量要不要拆板补进去、后者衡量本策略
    # 相对现场历史做法的激进度。任一族全 1.0 => 表为空 => 逐位等价。
    _BAM = P.get("bam"); _PRH = P.get("prh"); _NOB = P.get("nob")
    _RQS = P.get("rqs"); _RQW = P.get("rqw")
    if _BAM or _PRH or _NOB or _RQS or _RQW:
        for _k in list(out):
            _q0 = out[_k]
            _mm = 1.0
            if _BAM:
                _a = int(_C_box_age.get(_k, 0.0))
                if _a < 0:
                    _a = 0
                elif _a > 17:
                    _a = 17
                _t = _BAM.get(_a)
                if _t is not None:
                    _mm *= _t
            if _PRH:
                _pr = _C_priority.get(_k, 0.0)
                _t = _PRH.get(int(_pr) // 100 if _pr > 0 else -1)
                if _t is not None:
                    _mm *= _t
            if _NOB:
                _n = int(_C_n_orders.get(_k, 0.0))
                if _n < 0:
                    _n = 0
                elif _n > 5:
                    _n = 6 if _n <= 9 else 7
                _t = _NOB.get(_n)
                if _t is not None:
                    _mm *= _t
            if _RQS:
                _t = _RQS.get(_cbk(_q0 / (float(sms.get(_k, 0) or 0) + 1.0), P["rsc"]))
                if _t is not None:
                    _mm *= _t
            if _RQW:
                _t = _RQW.get(_cbk(_q0 / (_R_water_hist.get(_k, 0.0) + 1.0), P["rwc"]))
                if _t is not None:
                    _mm *= _t
            if _mm != 1.0:
                out[_k] = _q0 * _mm

    # ───────── v47 第二批分桶末端倍率 ─────────
    # prl: priority 个位(三位码 X0Y 的 Y, 数据里只有 1..6) —— prh 只切了百位。
    # wgb/aab/dpb: 件重 / 立库库龄 / DPS 当日投料前瞻的分桶。
    #   aab 的动机: grpscan 扫过的 208 条单组谓词里 `asrs_age>20` 是唯一边际为正的。
    # qmb: **水位自身量级**分桶。边际定价(多报一箱要 >90.8% 精确率才赚, 砍一箱只要
    #   >9.2%)在大单/小单上量级完全不同, 这条曲线让搜索自己找该在哪个量级收手。
    # rqm/rqi: 水位/本窗 rem、水位/今日已走量(sh_inc)的比值分位。
    # 任一族全 1.0 => 表为空 => 与加它们之前逐位等价。
    _PRL = P.get("prl"); _WGB = P.get("wgb"); _AAB = P.get("aab")
    _DPB = P.get("dpb"); _QMB = P.get("qmb"); _RQM = P.get("rqm"); _RQI = P.get("rqi")
    if _PRL or _WGB or _AAB or _DPB or _QMB or _RQM or _RQI:
        _C_weight = F["weight"]
        for _k in list(out):
            _q0 = out[_k]
            _mm = 1.0
            if _PRL:
                _pr = _C_priority.get(_k, 0.0)
                if _pr > 0:
                    _t = _PRL.get(int(_pr) % 10)
                    if _t is not None:
                        _mm *= _t
            if _WGB:
                _wv = _C_weight.get(_k, 0.0)
                if _wv > 0:
                    _t = _WGB.get(_cbk(_wv, P["wgc"]))
                    if _t is not None:
                        _mm *= _t
            if _AAB:
                _av = _C_asrs_age.get(_k, 0.0)
                if _av > 0:
                    _t = _AAB.get(_cbk(_av, P["aac"]))
                    if _t is not None:
                        _mm *= _t
            if _DPB:
                _dv = _C_dps_today.get(_k, 0.0)
                if _dv > 0:
                    _t = _DPB.get(_cbk(_dv, P["dpc"]))
                    if _t is not None:
                        _mm *= _t
            if _QMB:
                _t = _QMB.get(_cbk(_q0, P["qmc"]))
                if _t is not None:
                    _mm *= _t
            if _RQM:
                _t = _RQM.get(_cbk(_q0 / (float(rem.get(_k, 0) or 0) + 1.0), P["rmc"]))
                if _t is not None:
                    _mm *= _t
            if _RQI:
                _t = _RQI.get(_cbk(_q0 / (d_inc.get(_k, 0.0) + 1.0), P["ric"]))
                if _t is not None:
                    _mm *= _t
            if _mm != 1.0:
                out[_k] = _q0 * _mm

    # ───────── v48 第三批: 其余密集列的量级分桶 + 两族比值 ─────────
    # water_hist(11535 对) / s_ms(11251) / shipped_today(6233) / dps_next(6235) /
    # ess(3835) / prod_ahead(2870) / rem(1966) / picked_prior(858) / asrs_box(126)
    # 全部只以线性项或硬阈值出现过, 分桶给分段常数形状。
    # rqa/rqd 是「水位/立库折箱」「水位/DPS 当日投料」两条比值分位 —— 前者衡量
    # 拆板补货压力, 后者衡量今天还会不会有新货进来。
    _B2 = [(P.get(_n), F[_c], P[_n + 'c']) for _n, _c, _cut in _BK2]
    _RQA = P.get("rqa"); _RQD = P.get("rqd")
    if _RQA or _RQD or any(_t[0] for _t in _B2):
        for _k in list(out):
            _q0 = out[_k]
            _mm = 1.0
            for _tab, _col, _cut in _B2:
                if not _tab:
                    continue
                _v = _col.get(_k, 0.0)
                if _v > 0:
                    _t = _tab.get(_cbk(_v, _cut))
                    if _t is not None:
                        _mm *= _t
            if _RQA:
                _t = _RQA.get(_cbk(_q0 / (_C_asrs_box.get(_k, 0.0) + 1.0), P["rac"]))
                if _t is not None:
                    _mm *= _t
            if _RQD:
                _t = _RQD.get(_cbk(_q0 / (_C_dps_today.get(_k, 0.0) + 1.0), P["rdc"]))
                if _t is not None:
                    _mm *= _t
            if _mm != 1.0:
                out[_k] = _q0 * _mm

    # ───────── v51 跨日历史列的量级分桶 + 四条历史比值分位 ─────────
    # h_ewm/h_mx/h_avg/h_frq/h_lag/h_std 是「这个 SKU 平时走多少、走得勤不勤」的
    # 唯一来源, 此前只有线性项。air/rem_bulk/rem_ds/rem_fd 同理。
    # rqe/rqx/rqg/rql = 水位相对历史常态的比值分位 —— 边际箱该不该报, 条件在这。
    _B3 = [(P.get(_n), F[_c], P[_n + 'c']) for _n, _c, _cut in _BK3]
    _R3 = [(P.get(_n), F[_c], P[_n + 'c']) for _n, _c in _RQ3]
    if any(_t[0] for _t in _B3) or any(_t[0] for _t in _R3):
        for _k in list(out):
            _q0 = out[_k]
            _mm = 1.0
            for _tab, _col, _cut in _B3:
                if not _tab:
                    continue
                _v = float(_col.get(_k, 0) or 0)
                if _v > 0:
                    _t = _tab.get(_cbk(_v, _cut))
                    if _t is not None:
                        _mm *= _t
            for _tab, _col, _cut in _R3:
                if not _tab:
                    continue
                _t = _tab.get(_cbk(_q0 / (float(_col.get(_k, 0) or 0) + 1.0), _cut))
                if _t is not None:
                    _mm *= _t
            if _mm != 1.0:
                out[_k] = _q0 * _mm

    # ───────── v52 跨列比值分桶 ─────────
    # 「今天已经走了几倍于日常」「需求相对现货多大压力」这类判断不含当前水位, 而
    # 1D 表的乘积(=log 可加的 GAM)表达不了 log(a/b): 那要求两族桶高互为相反数,
    # 与各自还要拟合自身边际效应直接冲突。所以这是独立的一块自由度。
    _RZ = [(P.get(_n), F[_a], F[_b], P[_n + 'c']) for _n, _a, _b in _RZL]
    if any(_t[0] for _t in _RZ):
        for _k in list(out):
            _mm = 1.0
            for _tab, _fa, _fb, _cut in _RZ:
                if not _tab:
                    continue
                _num = float(_fa.get(_k, 0) or 0)
                if _num <= 0:
                    continue
                _t = _tab.get(_cbk(_num / (float(_fb.get(_k, 0) or 0) + 1.0), _cut))
                if _t is not None:
                    _mm *= _t
            if _mm != 1.0:
                out[_k] = out[_k] * _mm

    # ───────── v49 二维交互桶 ─────────
    # 到这里为止所有末端倍率都是各列 1D 表的**乘积**(取 log 后可加 => 本质是 GAM),
    # 交互项是这个结构在数学上表达不了的那一半。轴 'qm' 取水位自身量级 —— 「在这个
    # 上下文下、这个量级的水位该收还是该放」正是边际定价要的条件分位校准: 多报一箱
    # 需 >90.8% 精确率, 而该阈值在不同现货/历史/库龄条件下显然不同。
    # 表空(全 1.0) => 整条通路关闭, 与加它之前逐位等价。
    # v64: 本窗列取值缓存。IX 与 IX3 的非 'qm' 轴大量共用同一个特征字典, 而两个块
    # 之间不增删 out 的键 => 同一批 SKU 的列取值可以只算一次(键 = id(特征字典))。
    _CC = {}
    _IX = P.get("ix") or ()
    if _IX:
        # 桶号提到表循环外: 两条轴的取值按列去重、桶号按 (列,切点) 去重(见 _mkbk)。
        _CO, _BK, _MP = _mkbk([(None if _t[0] == 'qm' else F[_t[0]], _t[2]) for _t in _IX]
                              + [(None if _t[1] == 'qm' else F[_t[1]], _t[3]) for _t in _IX])
        _n = len(_IX)
        _IXR = [(_MP[_i], _MP[_n + _i], _IX[_i][4]) for _i in range(_n)]
        _ks = list(out)
        if _np is not None and len(_ks) >= _NPMIN:
            _nk = len(_ks)
            if _CC.get('n') != _nk:                     # 列缓存只在同一批 SKU 内有效
                _CC.clear(); _CC['n'] = _nk; _CC['z'] = [0.0] * _nk
            _zs = _CC['z']
            _q0a = _np.fromiter(map(out.get, _ks, _zs), dtype=_np.float64, count=_nk)
            _cv = []
            for _f in _CO:
                if _f is None:                              # 'qm' 轴 = 该 SKU 当前水位
                    _cv.append(_q0a); continue
                _a = _CC.get(id(_f))
                if _a is None:
                    # map(dict.get, keys, zeros) 全程在 C 层迭代, 比生成器快 1.6x(实测)
                    _a = _np.fromiter(map(_f.get, _ks, _zs), dtype=_np.float64, count=_nk)
                    _CC[id(_f)] = _a
                _cv.append(_a)
            _bb = _bkvec(_BK, _cv, _nk)
            _mma = _np.ones(_nk, dtype=_np.float64)
            for _i in range(_n):
                _ia, _ib, _tab = _IXR[_i]
                _fl, _d1 = _IXD[_i]
                _mma *= _fl[_bb[_ia] * _d1 + _bb[_ib]]      # 表序不变 => 乘积逐位不变
            _rs = _q0a * _mma
            for _i in _np.nonzero(_mma != 1.0)[0]:          # _mm==1.0 的位置原本不写
                out[_ks[_i]] = float(_rs[_i])
        else:
            for _k in _ks:
                _q0 = out[_k]
                _vs = [_q0 if _f is None else _f.get(_k, 0.0) for _f in _CO]
                _b = [_br(_cu, _vs[_ci]) if _s else _cbk(_vs[_ci], _cu)
                      for _ci, _cu, _s in _BK]
                _mm = 1.0
                for _ia, _ib, _tab in _IXR:
                    _t = _tab.get((_b[_ia], _b[_ib]))
                    if _t is not None:
                        _mm *= _t
                if _mm != 1.0:
                    out[_k] = _q0 * _mm

    # ───────── v59 三阶交互桶 ─────────
    # 上面的 IX 是 2D 表的**乘积** => log 域可加 => 只能表达 f(a,b)+g(b,c)+...,
    # 表达不了真正的 f(a,b,c)。三阶正是这一半: 边际定价阈值(多报一箱需 41.7%~93.5%
    # 精确率)同时依赖「水位量级 x 现货余量 x 库龄」三者 —— 「小水位+现货紧+货龄老」
    # 与「小水位+现货紧+货龄新」的该不该推结论相反, 而这在两张 2D 表相乘里只能
    # 被表达成两个边际效应的叠加。表空(全 1.0) => 整张跳过, 与加它之前逐位等价。
    _IX3 = P.get("ix3") or ()
    if _IX3:
        # 三条轴同样两级去重: 72 张表 216 次轴查询 -> 12 列取值 + 24 次桶化。
        _CO, _BK, _MP = _mkbk([(None if _t[0] == 'qm' else F[_t[0]], _t[3]) for _t in _IX3]
                              + [(None if _t[1] == 'qm' else F[_t[1]], _t[4]) for _t in _IX3]
                              + [(None if _t[2] == 'qm' else F[_t[2]], _t[5]) for _t in _IX3])
        _n = len(_IX3)
        _IX3R = [(_MP[_i], _MP[_n + _i], _MP[2 * _n + _i], _IX3[_i][6]) for _i in range(_n)]
        _ks = list(out)
        if _np is not None and len(_ks) >= _NPMIN:
            _nk = len(_ks)
            if _CC.get('n') != _nk:                     # 列缓存只在同一批 SKU 内有效
                _CC.clear(); _CC['n'] = _nk; _CC['z'] = [0.0] * _nk
            _zs = _CC['z']
            _q0a = _np.fromiter(map(out.get, _ks, _zs), dtype=_np.float64, count=_nk)
            _cv = []
            for _f in _CO:
                if _f is None:                              # 'qm' 轴 = 该 SKU 当前水位
                    _cv.append(_q0a); continue
                _a = _CC.get(id(_f))
                if _a is None:
                    # map(dict.get, keys, zeros) 全程在 C 层迭代, 比生成器快 1.6x(实测)
                    _a = _np.fromiter(map(_f.get, _ks, _zs), dtype=_np.float64, count=_nk)
                    _CC[id(_f)] = _a
                _cv.append(_a)
            _bb = _bkvec(_BK, _cv, _nk)
            _mma = _np.ones(_nk, dtype=_np.float64)
            for _i in range(_n):
                _ia, _ib, _ic, _tab = _IX3R[_i]
                _fl, _d1, _d2 = _IX3D[_i]
                _mma *= _fl[(_bb[_ia] * _d1 + _bb[_ib]) * _d2 + _bb[_ic]]
            _rs = _q0a * _mma
            for _i in _np.nonzero(_mma != 1.0)[0]:
                out[_ks[_i]] = float(_rs[_i])
        else:
            for _k in _ks:
                _q0 = out[_k]
                _vs = [_q0 if _f is None else _f.get(_k, 0.0) for _f in _CO]
                _b = [_br(_cu, _vs[_ci]) if _s else _cbk(_vs[_ci], _cu)
                      for _ci, _cu, _s in _BK]
                _mm = 1.0
                for _ia, _ib, _ic, _tab in _IX3R:
                    _t = _tab.get((_b[_ia], _b[_ib], _b[_ic]))
                    if _t is not None:
                        _mm *= _t
                if _mm != 1.0:
                    out[_k] = _q0 * _mm

    # ───────── v50 末端加性偏移(分段仿射) ─────────
    # 此前所有末端修正都是乘性的 => 分段线性且必过原点。加性偏移让「这个量级整体
    # 加/减半箱」成为可表达的动作 —— 边际箱定价(>92% 精确率才该加)本就是加性的。
    _QMO = P.get("qmo")
    if _QMO and any(_QMO):
        _qmc = P["qmc"]
        for _k in list(out):
            _q0 = out[_k]
            _o = _QMO[_cbk(_q0, _qmc)]
            if _o:
                _v = _q0 + _o
                out[_k] = _v if _v > 0.0 else 0.0
        for _k in [_k for _k, _v in out.items() if _v <= 0.0]:
            out.pop(_k, None)

    # ───────── v50 末端再取整 ─────────
    # 现有取整在主档内部就做完了, 之后 pgm/bam/qmb/ix 一串末端乘性倍率又把水位打回
    # 小数。ACT 是整箱数, 与评分口径对齐的是**最终**水位取整。偏置按量级分桶:
    # 小水位 SKU 抹掉小数会直接丢掉整个命中, 大水位 SKU 抹掉几乎无损。
    if P.get("fro_on"):
        _FRO = P["fro"]; _qmc = P["qmc"]
        for _k in list(out):
            _v = out[_k]
            if _v >= 1.0:
                _t = float(int(_v + _FRO[_cbk(_v, _qmc)]))
                if _t > 0:
                    out[_k] = _t

    # 统一 sh_inc 上封: 三档合并后再按「今天到此刻已经走掉多少」封一遍顶。
    # 与各档自己的上封是嵌套关系, 搜索时可以只留其中一层。
    fin_sicl = P["fin_sicl"]
    if fin_sicl > 0 and w >= P["si_w"]:
        for k in list(out):
            _si = d_inc.get(k, 0.0)
            if _si > 0 and out[k] > fin_sicl * _si:
                out[k] = fin_sicl * _si

    # ───────── 合法性收口: 只推荐**本窗候选清单**里的 SKU(最严口径) ─────────
    # information.md / gt.json 澄清项逐字:「候选清单是**本窗**允许推荐的 SKU 范围」。
    # 取最严的字面读法: 第 w 窗返回的键必须 ⊆ ctx["_window_skus"](w)。
    #   - 跨日 _H["seen"]/_H["frq"] 里今天没进过候选清单的 SKU: 越界, 剔除。
    #   - 当日累计候选集 _cst 里「今天进过别的窗、但不在本窗」的 SKU: 也越界, 剔除。
    #     (曾用 _cst 做边界, 理由是当日水位本就取六窗最大、在 w=1 报它等价; 但那要求
    #      用 w=5 的信息去改 w=1 的输出, 不是一个逐窗因果策略能做到的事 —— 判为越界。)
    # 覆盖面不因此损失: ∪_w cands(w) = _cst, 所以每个当日候选都能在**它自己在册的窗**
    # 里拿到水位, 当日水位取六窗最大后结果同样进推荐集(见 ε 档 eps_uni=0 + eps_once)。
    # ★无条件生效(不受任何参数控制), 保证搜索只能在合法空间里走。
    _cwin = set(cands)
    if _cwin:
        for _k in [_k for _k in out if _k not in _cwin]:
            del out[_k]

    # 全量码板整形: 三档合起来的单窗码板量仍可能顶破码垛能力(1440 箱/h x 4h = 5760),
    # 最后统一按码板成本从大到小摘一遍 —— 当日水位取六窗最大, 被摘的 SKU 在别的
    # 决策窗照样给水位, 相当于把码板作业错峰摊开, 不丢命中率。
    # ───────── v67 cov: 末端覆盖清扫 ─────────
    # 修正链(pgm/bam/qmb/ix/fro/qmo/fin_sicl)跑完之后, 本窗候选里仍然「当日累计
    # 水位 = 0」的 SKU 就是评估器眼里真正漏推的那批。按现货升序(码板最便宜的先)
    # 补 ε 水位, 直到本窗码板额度 cov_room 用完。额度允许超 5760 —— 后面紧跟的
    # `_pal_trim` 会按码板成本从大到小摘回来, 等价于「先铺开再收敛」。
    # 键一律取自 cands(本窗候选清单), 合法性收口已在上面跑过, 不会越界。
    if P.get("cov_on") and w >= P["cov_w"]:
        _cvr = P["cov_room"]; _wdc = _ST["wd"]
        _cve = P["eps_c"] if P["eps_c"] > 0.0 else 1e-9
        for _k, _v in out.items():
            _t = (sms.get(_k) or 0.0) - _v
            if _t > 0:
                _cvr -= _t
        _cvsf = P["cov_sfull"]; _cvsx = P["cov_smax"]
        _cvpf = P["cov_pf"]; _cvpk = P["cov_pk"]; _cvn = P["cov_n"]
        _cvhf = _H["frq"]
        _cvp = []
        for _k in cands:
            if (out.get(_k) or 0.0) > 0.0 or (_wdc.get(_k) or 0.0) > 0.0:
                continue
            _sv = float(sms.get(_k, 0) or 0)
            if 0.0 < _sv <= _cvsf:
                out[_k] = _sv
                continue
            if _cvsx > 0 and _sv > _cvsx:
                continue
            _cvp.append(((_sv + _cvpk) / (1.0 + _cvpf * (_cvhf.get(_k) or 0.0)), _sv, _k))
        _cvp.sort()
        _cvc = 0
        for _pri, _sv, _k in _cvp:
            if _cvn and _cvc >= _cvn:
                break
            if _sv > _cvr:
                continue
            out[_k] = _cve
            _cvr -= _sv
            _cvc += 1

    _pal_trim(out, sms, P["fin_pal_cap"], _tvw_fin)
    # 记下自己报出的当日水位(各窗最大, 与评估器的 Rec Carton Qty 同口径),
    # 明天开工拿到「昨日实发量」时就能算出自己的低报/高报倍率 —— 闭环校准的输入。
    _wd = _ST["wd"]
    for _k, _v in out.items():
        if _v > _wd.get(_k, 0.0):
            _wd[_k] = _v

    # ───────── v68 末端量级微整形 + 末端下托 / 上封 ─────────
    # 位置: 所有乘性修正、码板整形(_pal_trim)、候选合法性收口都跑完之后, 也在
    # 自报当日水位 _wd 之后 —— 这一层只改**报出去的**水位, 不进闭环校准的输入
    # (i32 的 wrapper 实测就是这个位置, +5.88e-04 由此复现)。
    # 只对**已在 out 里**的 SKU 生效, 绝不新增键 => 候选清单合法性不会被破坏。
    _QMF = P.get("qmf")
    if _QMF:
        _qfc = P["qmfc"]
        for _k, _v in list(out.items()):
            _m = _QMF[_cbk(_v, _qfc)]
            if _m != 1.0:
                out[_k] = _v * _m
    _FFL = P.get("ffl")
    if _FFL:
        for _n, _c in _FFL.items():
            _f = F.get(_n)
            if not _f:
                continue
            for _k, _v in list(out.items()):
                _fv = _f.get(_k)
                if _fv:
                    _t = _c * float(_fv)
                    if _t > _v:
                        out[_k] = _t
    _FCP = P.get("fcp")
    if _FCP:
        for _n, _c in _FCP.items():
            _f = F.get(_n)
            if not _f:
                continue
            for _k, _v in list(out.items()):
                _fv = _f.get(_k)
                if _fv:
                    _t = _c * float(_fv)
                    if _t < _v:
                        out[_k] = _t

    # ───────── v69 末端线性组合下托 / 上封 ─────────
    # 硬下界是加性的: 当日实发 >= (今日已走增量) + (二次待发) + ... 。单条
    # max(v, c*f) 只能取其中最大的一路, 表达不了和 —— 这一族把和放开。
    _FLIN = P.get("flin")
    _flc = P["flin_c"]
    if _FLIN or _flc > 0.0:
        _flg = P["flin_g"]
        _acc = {}
        for _n, _c in _FLIN.items():
            _f = F.get(_n)
            if not _f:
                continue
            for _k in out:
                _fv = _f.get(_k)
                if _fv:
                    _acc[_k] = _acc.get(_k, 0.0) + _c * float(_fv)
        for _k, _v in list(out.items()):
            _t = _flg * (_flc + _acc.get(_k, 0.0))
            if _t > _v:
                out[_k] = _t
    if P.get("clin_on"):
        _CLIN = P.get("clin") or {}
        _clg = P["clin_g"]; _clc = P["clin_c"]
        _acc = {}
        for _n, _c in _CLIN.items():
            _f = F.get(_n)
            if not _f:
                continue
            for _k in out:
                _fv = _f.get(_k)
                if _fv:
                    _acc[_k] = _acc.get(_k, 0.0) + _c * float(_fv)
        for _k, _v in list(out.items()):
            _t = _clg * (_clc + _acc.get(_k, 0.0))
            if _t < _v:
                out[_k] = _t
    return out
